package it.projectsrl.standpos.sales;

import it.projectsrl.standpos.common.TenantOwnedEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Table;
import java.time.Instant;
import java.time.LocalDate;
import java.util.UUID;

/**
 * An order taken at a register. {@code clientOrderId} is generated by the register so a retry returns this order
 * instead of creating another; {@code dailyNumber} restarts at 1 every business day of the venue.
 */
@Entity
@Table(name = "customer_order")
public class CustomerOrder extends TenantOwnedEntity {

    public enum Status {
        AWAITING_PAYMENT,
        PAID,
        CANCELLED,
        VOIDED
    }

    @Column(name = "venue_id", nullable = false, updatable = false)
    private UUID venueId;

    @Column(name = "device_id", nullable = false, updatable = false)
    private UUID deviceId;

    @Column(name = "shift_id", nullable = false, updatable = false)
    private UUID shiftId;

    @Column(name = "cashier_id", nullable = false, updatable = false)
    private UUID cashierId;

    @Column(name = "client_order_id", nullable = false, updatable = false)
    private UUID clientOrderId;

    @Column(name = "business_date", nullable = false, updatable = false)
    private LocalDate businessDate;

    @Column(name = "daily_number", nullable = false, updatable = false)
    private int dailyNumber;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private Status status;

    @Column(name = "total_cents", nullable = false, updatable = false)
    private long totalCents;

    @Column(name = "receipt_printed", nullable = false)
    private boolean receiptPrinted;

    @Column(name = "paid_at")
    private Instant paidAt;

    @Column(name = "voided_at")
    private Instant voidedAt;

    @Column(name = "voided_by")
    private UUID voidedBy;

    @Column(name = "void_reason")
    private String voidReason;

    protected CustomerOrder() {}

    public CustomerOrder(UUID venueId, UUID deviceId, UUID shiftId, UUID cashierId, UUID clientOrderId,
            LocalDate businessDate, int dailyNumber, long totalCents) {
        this.venueId = venueId;
        this.deviceId = deviceId;
        this.shiftId = shiftId;
        this.cashierId = cashierId;
        this.clientOrderId = clientOrderId;
        this.businessDate = businessDate;
        this.dailyNumber = dailyNumber;
        this.totalCents = totalCents;
        this.status = Status.AWAITING_PAYMENT;
    }

    public void markPaid(Instant now) {
        status = Status.PAID;
        paidAt = now;
    }

    public void markVoided(Instant now, UUID approvedBy, String reason) {
        status = Status.VOIDED;
        voidedAt = now;
        voidedBy = approvedBy;
        voidReason = reason;
    }

    public void markReceiptPrinted() {
        receiptPrinted = true;
    }

    public UUID getVenueId() {
        return venueId;
    }

    public UUID getDeviceId() {
        return deviceId;
    }

    public UUID getShiftId() {
        return shiftId;
    }

    public UUID getCashierId() {
        return cashierId;
    }

    public UUID getClientOrderId() {
        return clientOrderId;
    }

    public LocalDate getBusinessDate() {
        return businessDate;
    }

    public int getDailyNumber() {
        return dailyNumber;
    }

    public Status getStatus() {
        return status;
    }

    public long getTotalCents() {
        return totalCents;
    }

    public boolean isReceiptPrinted() {
        return receiptPrinted;
    }

    public Instant getPaidAt() {
        return paidAt;
    }

    public Instant getVoidedAt() {
        return voidedAt;
    }

    public UUID getVoidedBy() {
        return voidedBy;
    }

    public String getVoidReason() {
        return voidReason;
    }
}
